create policy happiness_activity_delegate_read on public.documentations for select to authenticated using ((select auth.uid())='a5422c4c-4533-4b18-8103-5d0fe9e273ce'::uuid and deleted_at is null and activity_type <> 'اجتماع' and (activity_type='لجنة السعادة' or details->'happiness'->>'schemaVersion'='1' or details->'projects' ? 'لجنة السعادة' or 'لجنة السعادة'=any(documentation_private.legacy_tag_names(projects))));
